// FILE: p2p-kids-admin/src/lib/categoryService.ts
// ADMIN-V3-003: Category CRUD service
// Module: MODULE-12-ADMIN-V3-CATEGORIES

import { createClient } from '@supabase/supabase-js';
import type {
  Category,
  CreateCategoryInput,
  UpdateCategoryInput,
  ValidationResult,
  CategoryReorderItem,
  IconType,
  CategorySPPreview,
} from '../types/category';
import {
  DuplicateNameError,
  CategoryNotEmptyError,
  SPRateOutOfRangeError,
  IconUploadError,
} from '../types/errors';

// Name validation regex: 3-50 chars, alphanumeric + spaces only
const NAME_REGEX = /^[A-Za-z0-9 ]{3,50}$/;

// SP rate bounds (legal-safety guardrails — DO NOT widen without legal review)
const SP_EARNING_MIN = 1.05;
const SP_EARNING_MAX = 1.40;
const SP_SPENDING_CAP_MIN = 50;
const SP_SPENDING_CAP_MAX = 80;

// Icon upload constraints
const MAX_ICON_SIZE_KB = 500;
const MIN_ICON_DIMENSIONS = 100; // pixels
const ALLOWED_ICON_TYPES = ['image/png', 'image/svg+xml'];

// Create Supabase client with service role (admin context)
// NOTE: Service role key must be provided via env var SUPABASE_SERVICE_ROLE_KEY
function getAdminClient() {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL || '';
  const supabaseKey =
    process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';

  const supabase = createClient(
    supabaseUrl,
    supabaseKey,
    {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    }
  );
  return supabase;
}

/**
 * Validate category name format (regex + length)
 * Does NOT check uniqueness (use checkCategoryUniqueness separately)
 */
export function validateCategoryName(name: string): ValidationResult {
  if (!name || name.trim().length === 0) {
    return { valid: false, error: 'Category name is required.' };
  }

  if (!NAME_REGEX.test(name)) {
    return {
      valid: false,
      error: 'Name must be 3–50 characters, letters, numbers, and spaces only.',
    };
  }

  return { valid: true };
}

/**
 * Check if category name already exists (case-insensitive)
 * @param name - Category name to check
 * @param excludeId - Optional category ID to exclude (for updates)
 * @returns { exists: boolean, existingId?: string }
 */
export async function checkCategoryUniqueness(
  name: string,
  excludeId?: string
): Promise<{ exists: boolean; existingId?: string }> {
  const supabase = getAdminClient();

  let query = supabase
    .from('categories')
    .select('id, name')
    .ilike('name', name); // Case-insensitive match

  if (excludeId) {
    query = query.neq('id', excludeId);
  }

  const { data, error } = await query.maybeSingle();

  if (error) {
    console.error('[categoryService] uniqueness check failed:', error);
    // Graceful degradation: assume unique on DB error
    return { exists: false };
  }

  return {
    exists: !!data,
    existingId: data?.id,
  };
}

/**
 * Get all categories (optionally filtered by active status)
 * @param includeInactive - If false, only return is_active=true (default true for admin)
 * @param orderBy - Sort field (default 'display_order')
 */
export async function getCategories(
  includeInactive = true,
  orderBy: 'display_order' | 'name' | 'item_count' = 'display_order'
): Promise<Category[]> {
  const supabase = getAdminClient();

  let query = supabase.from('categories').select('*');

  if (!includeInactive) {
    query = query.eq('is_active', true);
  }

  // Apply ordering
  if (orderBy === 'display_order') {
    query = query.order('display_order', { ascending: true }).order('name', { ascending: true });
  } else if (orderBy === 'name') {
    query = query.order('name', { ascending: true });
  } else if (orderBy === 'item_count') {
    query = query.order('item_count', { ascending: false });
  }

  const { data, error } = await query;

  if (error) {
    throw new Error(`Failed to fetch categories: ${error.message}`);
  }

  return data || [];
}

/**
 * Get a single category by ID
 */
export async function getCategoryById(id: string): Promise<Category | null> {
  const supabase = getAdminClient();

  const { data, error } = await supabase
    .from('categories')
    .select('*')
    .eq('id', id)
    .maybeSingle();

  if (error) {
    throw new Error(`Failed to fetch category: ${error.message}`);
  }

  return data;
}

/**
 * Create a new category
 * @throws DuplicateNameError if name already exists (case-insensitive)
 * @throws SPRateOutOfRangeError if rates outside bounds
 */
export async function createCategory(input: CreateCategoryInput): Promise<Category> {
  const supabase = getAdminClient();

  // Validate name format
  const validation = validateCategoryName(input.name);
  if (!validation.valid) {
    throw new Error(validation.error);
  }

  // Check uniqueness
  const { exists, existingId } = await checkCategoryUniqueness(input.name);
  if (exists) {
    throw new DuplicateNameError(input.name, existingId!);
  }

  // Validate SP rates if provided
  const earningMultiplier = input.sp_earning_multiplier ?? 1.10;
  const spendingCap = input.sp_spending_cap_percent ?? 70;

  if (earningMultiplier < SP_EARNING_MIN || earningMultiplier > SP_EARNING_MAX) {
    throw new SPRateOutOfRangeError(
      'sp_earning_multiplier',
      earningMultiplier,
      SP_EARNING_MIN,
      SP_EARNING_MAX
    );
  }

  if (spendingCap < SP_SPENDING_CAP_MIN || spendingCap > SP_SPENDING_CAP_MAX) {
    throw new SPRateOutOfRangeError(
      'sp_spending_cap_percent',
      spendingCap,
      SP_SPENDING_CAP_MIN,
      SP_SPENDING_CAP_MAX
    );
  }

  // Get max display_order and add 1
  const { data: maxOrder } = await supabase
    .from('categories')
    .select('display_order')
    .order('display_order', { ascending: false })
    .limit(1)
    .maybeSingle();

  const displayOrder = (maxOrder?.display_order ?? 0) + 1;

  // Insert category
  const { data, error } = await supabase
    .from('categories')
    .insert({
      name: input.name,
      description: input.description ?? null,
      icon: input.icon ?? null,
      icon_url: input.icon_url ?? null,
      bonus_badge_icon_url: input.bonus_badge_icon_url ?? null,
      is_active: input.is_active ?? true,
      sp_earning_multiplier: earningMultiplier,
      sp_spending_cap_percent: spendingCap,
      sp_config_notes: input.sp_config_notes ?? null,
      display_order: displayOrder,
    })
    .select()
    .single();

  if (error) {
    throw new Error(`Failed to create category: ${error.message}`);
  }

  return data;
}

/**
 * Update an existing category
 * @throws DuplicateNameError if name change conflicts
 * @throws SPRateOutOfRangeError if rates outside bounds
 */
export async function updateCategory(
  id: string,
  input: UpdateCategoryInput
): Promise<Category> {
  const supabase = getAdminClient();

  // If name is being changed, validate and check uniqueness
  if (input.name !== undefined) {
    const validation = validateCategoryName(input.name);
    if (!validation.valid) {
      throw new Error(validation.error);
    }

    const { exists, existingId } = await checkCategoryUniqueness(input.name, id);
    if (exists) {
      throw new DuplicateNameError(input.name, existingId!);
    }
  }

  // Validate SP rates if provided
  if (input.sp_earning_multiplier !== undefined) {
    if (
      input.sp_earning_multiplier < SP_EARNING_MIN ||
      input.sp_earning_multiplier > SP_EARNING_MAX
    ) {
      throw new SPRateOutOfRangeError(
        'sp_earning_multiplier',
        input.sp_earning_multiplier,
        SP_EARNING_MIN,
        SP_EARNING_MAX
      );
    }
  }

  if (input.sp_spending_cap_percent !== undefined) {
    if (
      input.sp_spending_cap_percent < SP_SPENDING_CAP_MIN ||
      input.sp_spending_cap_percent > SP_SPENDING_CAP_MAX
    ) {
      throw new SPRateOutOfRangeError(
        'sp_spending_cap_percent',
        input.sp_spending_cap_percent,
        SP_SPENDING_CAP_MIN,
        SP_SPENDING_CAP_MAX
      );
    }
  }

  // Build update payload (exclude item_count, display_order — trigger/RPC only)
  const updatePayload: any = {};
  if (input.name !== undefined) updatePayload.name = input.name;
  if (input.description !== undefined) updatePayload.description = input.description;
  if (input.icon !== undefined) updatePayload.icon = input.icon;
  if (input.icon_url !== undefined) updatePayload.icon_url = input.icon_url;
  if (input.bonus_badge_icon_url !== undefined)
    updatePayload.bonus_badge_icon_url = input.bonus_badge_icon_url;
  if (input.is_active !== undefined) updatePayload.is_active = input.is_active;
  if (input.sp_earning_multiplier !== undefined)
    updatePayload.sp_earning_multiplier = input.sp_earning_multiplier;
  if (input.sp_spending_cap_percent !== undefined)
    updatePayload.sp_spending_cap_percent = input.sp_spending_cap_percent;
  if (input.sp_config_notes !== undefined)
    updatePayload.sp_config_notes = input.sp_config_notes;
  if (input.sp_rate_change_notify !== undefined)
    updatePayload.sp_rate_change_notify = input.sp_rate_change_notify;

  updatePayload.updated_at = new Date().toISOString();

  const { data, error } = await supabase
    .from('categories')
    .update(updatePayload)
    .eq('id', id)
    .select()
    .single();

  if (error) {
    throw new Error(`Failed to update category: ${error.message}`);
  }

  return data;
}

/**
 * Delete a category (only if item_count = 0)
 * @throws CategoryNotEmptyError if category has items
 */
export async function deleteCategory(id: string): Promise<void> {
  const supabase = getAdminClient();

  // Fetch category to check item_count
  const category = await getCategoryById(id);
  if (!category) {
    throw new Error('Category not found');
  }

  if (category.item_count > 0) {
    throw new CategoryNotEmptyError(id, category.item_count);
  }

  // Check if this is the "Other" category (name check case-insensitive)
  if (category.name.toLowerCase() === 'other') {
    throw new Error('Cannot delete the "Other" category — it is required by the system.');
  }

  const { error } = await supabase.from('categories').delete().eq('id', id);

  if (error) {
    throw new Error(`Failed to delete category: ${error.message}`);
  }
}

/**
 * Toggle category active status
 * Refuses to deactivate the "Other" category
 */
export async function toggleCategoryActive(id: string, isActive: boolean): Promise<Category> {
  const supabase = getAdminClient();

  // Fetch category to check if it's "Other"
  const category = await getCategoryById(id);
  if (!category) {
    throw new Error('Category not found');
  }

  if (!isActive && category.name.toLowerCase() === 'other') {
    throw new Error('Cannot deactivate the "Other" category — it is required by the system.');
  }

  return updateCategory(id, { is_active: isActive });
}

/**
 * Reorder categories via RPC (optimistic UI handles rollback on error)
 * Calls the reorder_categories(JSONB) SECURITY DEFINER RPC
 */
export async function reorderCategories(reorderItems: CategoryReorderItem[]): Promise<void> {
  const supabase = getAdminClient();

  const { error } = await supabase.rpc('reorder_categories', {
    category_orders: reorderItems,
  });

  if (error) {
    // Check if it's an admin role error
    if (error.message?.includes('Admin role required')) {
      throw new Error('Admin role required to reorder categories');
    }
    throw new Error(`Failed to reorder categories: ${error.message}`);
  }
}

/**
 * Upload category icon or bonus badge to Supabase Storage
 * @param categoryId - Category ID
 * @param file - File object (PNG or SVG)
 * @param iconType - 'category' or 'bonus_badge'
 * @returns Public URL of the uploaded icon
 * @throws IconUploadError on validation failure
 */
export async function uploadCategoryIcon(
  categoryId: string,
  file: File,
  iconType: IconType
): Promise<string> {
  const supabase = getAdminClient();

  // Validate file type
  if (!ALLOWED_ICON_TYPES.includes(file.type)) {
    throw new IconUploadError('bad_type');
  }

  // Validate file size
  const sizeKB = file.size / 1024;
  if (sizeKB > MAX_ICON_SIZE_KB) {
    throw new IconUploadError('too_large', `File size: ${sizeKB.toFixed(1)} KB`);
  }

  // For images, validate dimensions (PNG only — SVG is vector)
  if (file.type === 'image/png') {
    try {
      const dimensions = await getImageDimensions(file);
      if (dimensions.width < MIN_ICON_DIMENSIONS || dimensions.height < MIN_ICON_DIMENSIONS) {
        throw new IconUploadError(
          'too_small',
          `Min ${MIN_ICON_DIMENSIONS}×${MIN_ICON_DIMENSIONS}px required, got ${dimensions.width}×${dimensions.height}px`
        );
      }
    } catch (err: any) {
      if (err instanceof IconUploadError) throw err;
      // If dimension check fails, continue (SVG or browser limitation)
      console.warn('[uploadCategoryIcon] Could not validate dimensions:', err.message);
    }
  }

  // Build storage path
  const ext = file.type === 'image/svg+xml' ? 'svg' : 'png';
  const filePath = `category-icons/${categoryId}/${iconType}.${ext}`;

  // Delete existing file at same path (overwrite)
  const { error: deleteError } = await supabase.storage
    .from('category-icons')
    .remove([filePath]);

  if (deleteError) {
    console.warn('[uploadCategoryIcon] Could not delete existing file:', deleteError.message);
    // Continue anyway — upload will overwrite
  }

  // Upload file
  const { data: uploadData, error: uploadError } = await supabase.storage
    .from('category-icons')
    .upload(filePath, file, {
      cacheControl: '3600',
      upsert: true,
    });

  if (uploadError) {
    throw new IconUploadError('upload_failed', uploadError.message);
  }

  // Get public URL
  const { data: urlData } = supabase.storage
    .from('category-icons')
    .getPublicUrl(uploadData.path);

  if (!urlData?.publicUrl) {
    throw new IconUploadError('upload_failed', 'Could not generate public URL');
  }

  // Update category record with new URL
  const columnName = iconType === 'category' ? 'icon_url' : 'bonus_badge_icon_url';
  await updateCategory(categoryId, { [columnName]: urlData.publicUrl });

  return urlData.publicUrl;
}

/**
 * Calculate SP preview for a given category and price
 * Used for live preview in CategoryForm
 */
export function calculateCategorySPPreview(
  earningMultiplier: number,
  spendingCapPercent: number,
  price: number
): CategorySPPreview {
  return {
    price,
    earn_sp: Math.round(price * earningMultiplier),
    max_spend_sp: Math.floor((price * spendingCapPercent) / 100),
    spend_percent: spendingCapPercent,
  };
}

/**
 * Get categories with bonus earning multiplier (> 1.10) and active
 */
export async function getBonusCategories(): Promise<Category[]> {
  const supabase = getAdminClient();

  const { data, error } = await supabase
    .from('categories')
    .select('*')
    .eq('is_active', true)
    .gt('sp_earning_multiplier', 1.10)
    .order('sp_earning_multiplier', { ascending: false });

  if (error) {
    throw new Error(`Failed to fetch bonus categories: ${error.message}`);
  }

  return data || [];
}

// Helper: Get image dimensions from File object
function getImageDimensions(file: File): Promise<{ width: number; height: number }> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);

    img.onload = () => {
      URL.revokeObjectURL(url);
      resolve({ width: img.width, height: img.height });
    };

    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error('Failed to load image for dimension check'));
    };

    img.src = url;
  });
}

// FILE: p2p-kids-admin/src/lib/categorySuggestionService.ts
// ADMIN-V3-003: Category Suggestion service (approve/reject/merge)
// Module: MODULE-12-ADMIN-V3-CATEGORIES

import { createClient } from '@supabase/supabase-js';
import type {
  CategorySuggestion,
  ApproveSuggestionInput,
  MergeSuggestionInput,
  RejectSuggestionInput,
  SuggestionStatus,
} from '../types/category';
import { createCategory } from './categoryService';

function getAdminClient() {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL || '';
  const supabaseKey =
    process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';

  const supabase = createClient(
    supabaseUrl,
    supabaseKey,
    {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    }
  );
  return supabase;
}

/**
 * Get category suggestions (with optional status filter)
 * @param status - Filter by status (default: 'pending')
 * @param includeDetails - If true, join seller + item data
 */
export async function getCategorySuggestions(
  status?: SuggestionStatus,
  includeDetails = true
): Promise<CategorySuggestion[]> {
  const supabase = getAdminClient();

  let query = supabase.from('category_suggestions').select(
    includeDetails
      ? `
        *,
        seller:profiles!seller_id(id, full_name, email),
        item:items!item_id(id, name, status),
        merged_to_category:categories!merged_to_category_id(id, name)
      `
      : '*'
  );

  if (status) {
    query = query.eq('status', status);
  }

  query = query.order('created_at', { ascending: false });

  const { data, error } = await query;

  if (error) {
    throw new Error(`Failed to fetch category suggestions: ${error.message}`);
  }

  return (data as any) || [];
}

/**
 * Get count of pending suggestions (for badge count)
 */
export async function getPendingSuggestionCount(): Promise<number> {
  const supabase = getAdminClient();

  const { count, error } = await supabase
    .from('category_suggestions')
    .select('*', { count: 'exact', head: true })
    .eq('status', 'pending');

  if (error) {
    throw new Error(`Failed to count pending suggestions: ${error.message}`);
  }

  return count || 0;
}

/**
 * Approve a category suggestion
 * Creates a new category and reassigns the item in a single transaction
 * @param suggestionId - Suggestion ID
 * @param input - Category creation data + options
 * @param adminUserId - ID of the admin user approving
 * @throws Error if transaction fails at any step
 */
export async function approveCategorySuggestion(
  suggestionId: string,
  input: ApproveSuggestionInput,
  adminUserId: string
): Promise<void> {
  const supabase = getAdminClient();

  // 1. Fetch suggestion to get item_id
  const { data: suggestion, error: fetchError } = await supabase
    .from('category_suggestions')
    .select('*, item:items!item_id(id, status)')
    .eq('id', suggestionId)
    .single();

  if (fetchError || !suggestion) {
    throw new Error(`Failed to fetch suggestion: ${fetchError?.message || 'Not found'}`);
  }

  if (suggestion.status !== 'pending') {
    throw new Error(`Suggestion is already ${suggestion.status}`);
  }

  try {
    // 2. Create the new category
    const newCategory = await createCategory(input.categoryData);

    // 3. Reassign the item to the new category (if requested)
    const shouldReassign = input.reassignItem !== false; // default true
    if (shouldReassign) {
      const { error: itemUpdateError } = await supabase
        .from('items')
        .update({ category_id: newCategory.id })
        .eq('id', suggestion.item_id);

      if (itemUpdateError) {
        // Rollback: delete the category we just created
        await supabase.from('categories').delete().eq('id', newCategory.id);
        throw new Error(`Failed to reassign item: ${itemUpdateError.message}`);
      }
    }

    // 4. Update suggestion row
    const { error: suggestionUpdateError } = await supabase
      .from('category_suggestions')
      .update({
        status: 'approved' as SuggestionStatus,
        approved_by: adminUserId,
        reviewed_at: new Date().toISOString(),
      })
      .eq('id', suggestionId);

    if (suggestionUpdateError) {
      // Rollback: delete category and revert item
      await supabase.from('categories').delete().eq('id', newCategory.id);
      if (shouldReassign) {
        await supabase
          .from('items')
          .update({ category_id: suggestion.item_id })
          .eq('id', suggestion.item_id);
      }
      throw new Error(`Failed to update suggestion: ${suggestionUpdateError.message}`);
    }
  } catch (err: any) {
    console.error('[approveCategorySuggestion] Transaction failed:', err);
    throw err;
  }
}

/**
 * Reject a category suggestion (item stays in current category)
 * @param suggestionId - Suggestion ID
 * @param input - Optional admin note
 * @param adminUserId - ID of the admin user rejecting
 */
export async function rejectCategorySuggestion(
  suggestionId: string,
  input: RejectSuggestionInput,
  adminUserId: string
): Promise<void> {
  const supabase = getAdminClient();

  const { error } = await supabase
    .from('category_suggestions')
    .update({
      status: 'rejected' as SuggestionStatus,
      approved_by: adminUserId, // Track who rejected
      admin_note: input.admin_note || null,
      reviewed_at: new Date().toISOString(),
    })
    .eq('id', suggestionId)
    .eq('status', 'pending'); // Only reject pending suggestions

  if (error) {
    throw new Error(`Failed to reject suggestion: ${error.message}`);
  }
}

/**
 * Merge a suggestion into an existing category
 * Reassigns the item to the target category
 * @param suggestionId - Suggestion ID
 * @param input - Target category ID + optional note
 * @param adminUserId - ID of the admin user merging
 */
export async function mergeCategorySuggestion(
  suggestionId: string,
  input: MergeSuggestionInput,
  adminUserId: string
): Promise<void> {
  const supabase = getAdminClient();

  // 1. Fetch suggestion to get item_id
  const { data: suggestion, error: fetchError } = await supabase
    .from('category_suggestions')
    .select('*')
    .eq('id', suggestionId)
    .single();

  if (fetchError || !suggestion) {
    throw new Error(`Failed to fetch suggestion: ${fetchError?.message || 'Not found'}`);
  }

  if (suggestion.status !== 'pending') {
    throw new Error(`Suggestion is already ${suggestion.status}`);
  }

  // 2. Verify target category exists
  const { data: targetCategory, error: categoryError } = await supabase
    .from('categories')
    .select('id, name')
    .eq('id', input.target_category_id)
    .single();

  if (categoryError || !targetCategory) {
    throw new Error(`Target category not found: ${categoryError?.message || 'Not found'}`);
  }

  try {
    // 3. Reassign item to target category
    const { error: itemUpdateError } = await supabase
      .from('items')
      .update({ category_id: input.target_category_id })
      .eq('id', suggestion.item_id);

    if (itemUpdateError) {
      throw new Error(`Failed to reassign item: ${itemUpdateError.message}`);
    }

    // 4. Update suggestion row
    const { error: suggestionUpdateError } = await supabase
      .from('category_suggestions')
      .update({
        status: 'merged' as SuggestionStatus,
        approved_by: adminUserId,
        merged_to_category_id: input.target_category_id,
        admin_note: input.admin_note || null,
        reviewed_at: new Date().toISOString(),
      })
      .eq('id', suggestionId);

    if (suggestionUpdateError) {
      // Rollback: revert item category
      // Note: We don't know the original category here — best effort only
      console.error('[mergeCategorySuggestion] Failed to update suggestion after item reassignment');
      throw new Error(`Failed to update suggestion: ${suggestionUpdateError.message}`);
    }
  } catch (err: any) {
    console.error('[mergeCategorySuggestion] Transaction failed:', err);
    throw err;
  }
}

/**
 * Subscribe to realtime pending suggestion count updates
 * @param callback - Function called with new count when suggestions change
 * @returns Unsubscribe function
 */
export function subscribeToPendingSuggestions(
  callback: (count: number) => void
): () => void {
  const supabase = getAdminClient();

  // Initial count
  getPendingSuggestionCount().then(callback).catch(console.error);

  // Subscribe to changes
  const channel = supabase
    .channel('category_suggestions_pending')
    .on(
      'postgres_changes',
      {
        event: '*',
        schema: 'public',
        table: 'category_suggestions',
        filter: 'status=eq.pending',
      },
      () => {
        // Refetch count on any change
        getPendingSuggestionCount().then(callback).catch(console.error);
      }
    )
    .subscribe();

  // Return unsubscribe function
  return () => {
    supabase.removeChannel(channel);
  };
}

// FILE: p2p-kids-admin/src/lib/spConfigCategoryService.ts
// ADMIN-V3-003: SP Config service for category-specific SP calculations & analytics
// Module: MODULE-12-ADMIN-V3-CATEGORIES

import { createClient } from '@supabase/supabase-js';
import type {
  Category,
  CategorySPPreview,
  CategorySPAnalytics,
  AnomalyFlag,
} from '../types/category';
import { SPRateOutOfRangeError } from '../types/errors';

const SP_EARNING_MIN = 1.05;
const SP_EARNING_MAX = 1.40;
const SP_SPENDING_CAP_MIN = 50;
const SP_SPENDING_CAP_MAX = 80;

function getAdminClient() {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL || '';
  const supabaseKey =
    process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';

  const supabase = createClient(
    supabaseUrl,
    supabaseKey,
    {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    }
  );
  return supabase;
}

/**
 * Calculate SP earn/spend for a specific category and price
 * Used for: price suggestion cards, checkout UI, analytics preview
 * RULE: earn_sp = Math.round, max_spend_sp = Math.floor
 */
export function calculateCategorySP(
  categoryId: string,
  price: number,
  spEarningMultiplier: number,
  spSpendingCapPercent: number
): CategorySPPreview {
  return {
    price,
    earn_sp: Math.round(price * spEarningMultiplier),
    max_spend_sp: Math.floor((price * spSpendingCapPercent) / 100),
    spend_percent: spSpendingCapPercent,
  };
}

/**
 * Get bonus categories (sp_earning_multiplier > 1.10 AND is_active = true)
 * Ordered by multiplier DESC
 */
export async function getBonusCategories(): Promise<Category[]> {
  const supabase = getAdminClient();

  const { data, error } = await supabase
    .from('categories')
    .select('*')
    .eq('is_active', true)
    .gt('sp_earning_multiplier', 1.10)
    .order('sp_earning_multiplier', { ascending: false });

  if (error) {
    throw new Error(`Failed to fetch bonus categories: ${error.message}`);
  }

  return data || [];
}

/**
 * Update category SP rates and optionally trigger notification
 * @param categoryId - Category ID
 * @param earningMultiplier - New earning multiplier (1.05–1.40)
 * @param spendingCapPercent - New spending cap % (50–80)
 * @param notifyUsers - If true, enqueue banner notification (MODULE-14)
 * @param configNotes - Optional strategy notes (max 500 chars)
 * @throws SPRateOutOfRangeError if rates outside bounds
 */
export async function updateCategorySPRates(
  categoryId: string,
  earningMultiplier: number,
  spendingCapPercent: number,
  notifyUsers: boolean,
  configNotes?: string | null
): Promise<void> {
  // Validate ranges
  if (earningMultiplier < SP_EARNING_MIN || earningMultiplier > SP_EARNING_MAX) {
    throw new SPRateOutOfRangeError(
      'sp_earning_multiplier',
      earningMultiplier,
      SP_EARNING_MIN,
      SP_EARNING_MAX
    );
  }

  if (spendingCapPercent < SP_SPENDING_CAP_MIN || spendingCapPercent > SP_SPENDING_CAP_MAX) {
    throw new SPRateOutOfRangeError(
      'sp_spending_cap_percent',
      spendingCapPercent,
      SP_SPENDING_CAP_MIN,
      SP_SPENDING_CAP_MAX
    );
  }

  const supabase = getAdminClient();

  // Fetch category for notification banner copy
  const { data: category, error: fetchError } = await supabase
    .from('categories')
    .select('id, name')
    .eq('id', categoryId)
    .single();

  if (fetchError || !category) {
    throw new Error(`Category not found: ${fetchError?.message || 'Not found'}`);
  }

  // Update category
  const { error: updateError } = await supabase
    .from('categories')
    .update({
      sp_earning_multiplier: earningMultiplier,
      sp_spending_cap_percent: spendingCapPercent,
      sp_config_notes: configNotes ?? null,
      sp_rate_change_notify: notifyUsers, // Set flag for one-shot notification
      updated_at: new Date().toISOString(),
    })
    .eq('id', categoryId);

  if (updateError) {
    throw new Error(`Failed to update SP rates: ${updateError.message}`);
  }

  // If notifyUsers=true, enqueue banner notification via MODULE-14
  if (notifyUsers) {
    try {
      // TODO: Wire to MODULE-14 NotificationService.enqueueBanner
      // For now, log intent
      console.log(
        `[updateCategorySPRates] Notification banner requested for category "${category.name}" (multiplier: ${earningMultiplier})`
      );

      // Example payload for MODULE-14:
      // await NotificationService.enqueueBanner({
      //   title: `${category.name} now earns bonus SP!`,
      //   message: `Items in ${category.name} earn more Swap Points. List yours now!`,
      //   type: 'info',
      //   category: 'sp_rate_change',
      // });

      // Reset the notification flag
      await supabase
        .from('categories')
        .update({ sp_rate_change_notify: false })
        .eq('id', categoryId);
    } catch (notifyError: any) {
      console.error('[updateCategorySPRates] Banner notification failed:', notifyError.message);
      // Non-blocking: SP rates updated successfully, notification failed
    }
  }
}

/**
 * Get SP analytics per category for a given date range
 * @param dateRange - { start: ISO date, end: ISO date }
 * @returns Array of CategorySPAnalytics with velocity, gap, cash flow, anomaly flags
 */
export async function getSPAnalyticsByCategory(dateRange: {
  start: string;
  end: string;
}): Promise<CategorySPAnalytics[]> {
  const supabase = getAdminClient();

  // Aggregate points_transactions + items sold in date range
  // This is a simplified version — production should use a materialized view if slow
  const { data: categories, error: catError } = await supabase
    .from('categories')
    .select('id, name')
    .eq('is_active', true);

  if (catError) {
    throw new Error(`Failed to fetch categories: ${catError.message}`);
  }

  const analytics: CategorySPAnalytics[] = [];

  for (const category of categories || []) {
    // 1. Get items in this category sold in date range
    const { data: items, error: itemsError } = await supabase
      .from('items')
      .select('id, price')
      .eq('category_id', category.id)
      .eq('status', 'sold')
      .gte('created_at', dateRange.start)
      .lte('created_at', dateRange.end);

    if (itemsError) {
      console.error(`[getSPAnalyticsByCategory] Error fetching items for ${category.name}:`, itemsError);
      continue;
    }

    if (!items || items.length === 0) {
      // No data for this category in range
      continue;
    }

    // 2. Aggregate SP earned (seller) and spent (buyer) from points_transactions
    // Simplified: assume we have a points_transactions table with category_id FK
    // In reality, you'd join through items → transactions → points_transactions
    // For MVP, we'll calculate based on item prices and current category rates

    const { data: catData } = await supabase
      .from('categories')
      .select('sp_earning_multiplier, sp_spending_cap_percent')
      .eq('id', category.id)
      .single();

    if (!catData) continue;

    const totalEarnedSP = items.reduce((sum, item) => {
      return sum + Math.round(item.price * catData.sp_earning_multiplier);
    }, 0);

    // Spent SP: assume average 50% of max allowed (placeholder)
    const totalSpentSP = items.reduce((sum, item) => {
      const maxSpend = Math.floor((item.price * catData.sp_spending_cap_percent) / 100);
      return sum + maxSpend * 0.5; // Assume 50% utilization
    }, 0);

    // Calculate metrics
    const velocity = totalEarnedSP > 0 ? totalSpentSP / totalEarnedSP : 0;
    const gapPercent = totalEarnedSP > 0 ? ((totalEarnedSP - totalSpentSP) / totalEarnedSP) * 100 : 0;
    const avgCashPerTrade =
      items.reduce((sum, item) => sum + item.price, 0) / items.length;

    // Anomaly detection
    const anomalyFlags: AnomalyFlag[] = [];
    if (gapPercent > 10) anomalyFlags.push('hoarding');
    if (velocity < 0.5) anomalyFlags.push('low_velocity');
    if (velocity > 2) anomalyFlags.push('spending_spike');

    analytics.push({
      category_id: category.id,
      category_name: category.name,
      velocity,
      gap_percent: gapPercent,
      avg_cash_per_trade: avgCashPerTrade,
      anomaly_flags: anomalyFlags,
    });
  }

  return analytics.sort((a, b) => b.gap_percent - a.gap_percent);
}

