function get(name){
  const lines = env.split(/\r?\n/).filter(Boolean);
  let val='';
  for(const l of lines){
    if(l.startsWith(name+'=')) val=l.slice(name.length+1).trim();
  }
  return val.replace(/^"|"$/g,'');
}
