/**
 * File: p2p-kids-marketplace/src/components/listing/CategorySelectModal.tsx
 * MODULE-04 LISTING-V3-008: Category Select Modal
 * Task: LISTING-V3-008 - Full-screen category selection with search
 * 
 * Features:
 * - Search categories
 * - Recent 3 categories
 * - All categories list
 * - "Other" option with custom input
 */

import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  TextInput,
  Modal,
  StyleSheet,
  FlatList,
  SafeAreaView,
  Image,
} from 'react-native';

export interface Category {
  id: string;
  name: string;
  icon?: string | null;
  icon_url?: string | null;
}

export interface CategorySelectModalProps {
  visible: boolean;
  categories: Category[];
  recent: Category[];
  onSelect: (category: Category) => void;
  onSelectOther: (customName: string) => void;
  onClose: () => void;
  testID?: string;
}

export function CategorySelectModal({
  visible,
  categories,
  recent,
  onSelect,
  onSelectOther,
  onClose,
  testID = 'category-select-modal',
}: CategorySelectModalProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [showOtherInput, setShowOtherInput] = useState(false);
  const [customCategory, setCustomCategory] = useState('');

  const filteredCategories = categories.filter((cat) =>
    cat.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleSelectOther = () => {
    if (customCategory.trim().length > 0) {
      onSelectOther(customCategory.trim());
      setCustomCategory('');
      setShowOtherInput(false);
    }
  };

  const renderCategory = ({ item }: { item: Category }) => (
    <TouchableOpacity
      style={styles.categoryItem}
      onPress={() => {
        onSelect(item);
        setSearchQuery('');
      }}
      accessibilityLabel={`Select category: ${item.name}`}
      accessibilityRole="button"
      testID={`category-${item.id}`}
    >
      {item.icon_url ? (
        <Image
          source={{ uri: item.icon_url }}
          style={styles.categoryIconImage}
          resizeMode="cover"
        />
      ) : item.icon && item.icon.trim().length > 0 ? (
        <Text style={styles.categoryIcon}>{item.icon}</Text>
      ) : (
        <Text style={styles.categoryIcon}>📦</Text>
      )}
      <Text style={styles.categoryName}>{item.name}</Text>
    </TouchableOpacity>
  );

  return (
    <Modal
      visible={visible}
      animationType="slide"
      presentationStyle="fullScreen"
      onRequestClose={onClose}
      testID={testID}
    >
      <SafeAreaView style={styles.container}>
        <View style={styles.header}>
          <Text style={styles.title}>Select Category</Text>
          <TouchableOpacity
            onPress={onClose}
            accessibilityLabel="Close category selection"
            accessibilityRole="button"
            testID="close-modal"
          >
            <Text style={styles.closeButton}>×</Text>
          </TouchableOpacity>
        </View>

        <TextInput
          style={styles.searchInput}
          placeholder="Search categories..."
          value={searchQuery}
          onChangeText={setSearchQuery}
          autoCapitalize="none"
          autoCorrect={false}
          clearButtonMode="while-editing"
          accessibilityLabel="Search categories"
          testID="category-search-input"
        />

        {!showOtherInput && recent.length > 0 && searchQuery === '' && (
          <View style={styles.recentSection}>
            <Text style={styles.sectionTitle}>Recent</Text>
            <View style={styles.recentList}>
              {recent.map((cat) => (
                <TouchableOpacity
                  key={cat.id}
                  style={styles.recentChip}
                  onPress={() => onSelect(cat)}
                  accessibilityLabel={`Select recent category: ${cat.name}`}
                  testID={`recent-${cat.id}`}
                >
                  <Text style={styles.recentChipText}>{cat.name}</Text>
                </TouchableOpacity>
              ))}
            </View>
          </View>
        )}

        {!showOtherInput ? (
          <FlatList
            data={filteredCategories}
            renderItem={renderCategory}
            keyExtractor={(item) => item.id}
            ListEmptyComponent={
              <View style={styles.emptyState}>
                <Text style={styles.emptyText}>No categories found</Text>
              </View>
            }
            contentContainerStyle={styles.listContent}
          />
        ) : (
          <View style={styles.otherInputContainer}>
            <Text style={styles.otherLabel}>Enter custom category name:</Text>
            <TextInput
              style={styles.otherInput}
              placeholder="e.g., Baby Gear, Sports Equipment"
              value={customCategory}
              onChangeText={setCustomCategory}
              autoFocus
              maxLength={100}
              accessibilityLabel="Custom category name"
              testID="custom-category-input"
            />
            <Text style={styles.otherHint}>
              This will be sent to admin for review
            </Text>
            <View style={styles.otherActions}>
              <TouchableOpacity
                style={styles.otherCancelButton}
                onPress={() => {
                  setShowOtherInput(false);
                  setCustomCategory('');
                }}
                testID="cancel-other"
              >
                <Text style={styles.otherCancelText}>Cancel</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[
                  styles.otherSubmitButton,
                  customCategory.trim().length === 0 && styles.otherSubmitButtonDisabled,
                ]}
                onPress={handleSelectOther}
                disabled={customCategory.trim().length === 0}
                testID="submit-other"
              >
                <Text style={styles.otherSubmitText}>Submit</Text>
              </TouchableOpacity>
            </View>
          </View>
        )}

        {!showOtherInput && (
          <TouchableOpacity
            style={styles.otherButton}
            onPress={() => setShowOtherInput(true)}
            accessibilityLabel="Select other category not in list"
            accessibilityRole="button"
            testID="other-button"
          >
            <Text style={styles.otherButtonText}>+ Other (Custom Category)</Text>
          </TouchableOpacity>
        )}
      </SafeAreaView>
    </Modal>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingHorizontal: 16,
    paddingVertical: 12,
    borderBottomWidth: 1,
    borderBottomColor: '#E0E0E0',
  },
  title: {
    fontSize: 20,
    fontWeight: '600',
    color: '#000000',
  },
  closeButton: {
    fontSize: 36,
    color: '#999999',
    lineHeight: 36,
    width: 36,
    textAlign: 'center',
  },
  searchInput: {
    margin: 16,
    padding: 12,
    backgroundColor: '#F5F5F5',
    borderRadius: 8,
    fontSize: 16,
  },
  recentSection: {
    paddingHorizontal: 16,
    marginBottom: 16,
  },
  sectionTitle: {
    fontSize: 14,
    fontWeight: '600',
    color: '#666666',
    marginBottom: 12,
  },
  recentList: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
  },
  recentChip: {
    paddingHorizontal: 16,
    paddingVertical: 8,
    backgroundColor: '#E3F2FD',
    borderRadius: 16,
  },
  recentChipText: {
    fontSize: 14,
    color: '#1976D2',
    fontWeight: '500',
  },
  listContent: {
    paddingBottom: 100,
  },
  categoryItem: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 16,
    paddingHorizontal: 16,
    borderBottomWidth: 1,
    borderBottomColor: '#F0F0F0',
  },
  categoryIcon: {
    fontSize: 24,
    marginRight: 12,
  },
  categoryIconImage: {
    width: 32,
    height: 32,
